/* Purpose: explain AHJ Atlas's shipped mechanisms to the engineer or architect who
   puts their name on the output. Claims ledger: docs/TRUST_CLAIMS.md.
   If the implementation changes, this changes with it. A trust document that has
   drifted from the code is worse than none. */
import { FACTS as F } from './trust-facts.js';
export { FACTS } from './trust-facts.js';
const n=value=>Number(value).toLocaleString('en-US');
const minutes=value=>n(value/60000),seconds=value=>n(value/1000);
const sonnet=F.models.research.id,opus=F.models.review.id;
const local='No external destination. Your browser talks to the local app on this computer.';
const none='None.';
const researchAI=`${sonnet}: high effort for jurisdiction/codes, medium for contacts. ${opus}: medium for the evidence check and final report. Adaptive reasoning; no temperature is explicitly set. Research/evidence-check requests allow ${n(F.research.output)} output tokens; final reports ${n(F.research.reviewOutput)}. Saved conversations may retain an earlier model and request prefix until rebuilt.`;
const researchSent=`Project inputs, saved answers, selected briefs and source passages, tool results and conversation go to ${F.hosts.anthropic}. Token counting sends the request context too. Vendor web search uses model-written queries. Public source hosts receive requested URLs; ${F.hosts.census} receives the address if the US address tool is used. A visually inspected PDF page is sent as an image in the next model request.`;
const researchBounds=`Across research: ${n(F.research.searches)} searches and ${n(F.research.reads)} source reads. Ordinary stages allow ${n(F.research.rounds)} requests; the evidence check ${n(F.research.verificationRounds)}, final report ${n(F.research.reviewRounds)}. The evidence check has ${n(F.research.verificationSearches)} searches and ${n(F.research.verificationReads)} reads inside those totals. Real-time research checks a ${minutes(F.research.activeMs)}-minute accumulated active-work allowance before starting non-final stages; this is not a strict wall-clock deadline or dollar cap. Missing evidence stays a gap; completed work is billed even if the report is incomplete.`;
const chatAI=`Standard: ${sonnet}, high effort. Deep: ${sonnet}, max effort. Opus: ${opus}, xhigh effort. All use adaptive reasoning, ${n(F.chat.output)} maximum output tokens and no explicitly set temperature; all are real-time, even for a batch project.`;
const chatSent=`This project's inputs, answers, saved report/briefs/source excerpts, recent conversation and your message go to ${F.hosts.anthropic}, including for token counting. Lookups can add public-source text or a scanned-page image; native searches send model-written queries. Public source URLs and optional US Census address lookup also leave this computer.`;
const chatBounds=`One active reply per project; no global chat-worker cap is enforced across projects. Per reply: ${n(F.chat.requests)} requests, ${n(F.chat.toolCalls)} lookups, ${n(F.chat.searches)} searches (${n(F.chat.searchesPerRequest)} per request), ${n(F.chat.webReads)} public page reads and ${minutes(F.chat.activeMs)} minutes of nominal lookup allowance, with ${minutes(F.chat.wrapUpMs)} minutes reserved for finishing. A request gets at least ${minutes(F.chat.answerMs)} minutes to answer, subject to the provider stream deadline; total elapsed time can exceed the lookup allowance. No spend cap. Failed ambiguous responses keep their estimated cost pending; failure is not automatically resubmitted.`;
const row=(id,title,you,runs,sent,ai,bounds)=>({id,title,you,runs,sent,ai,bounds});
export const RUNTIME=[
  row('U01','Prepare your project','Choose New research; fill fields; expand Add project context; change discipline, building use or processing mode.','The form changes locally. The default building use is Hyperscale data center, and the default mode is Research now. Custom fields are enabled only when selected. Nothing is queued before Start research.',local,none,'Unsaved form fields are not a project backup. There is no global undo or file-drop import; changing a selector does not buy a model response.'),
  row('U02','Read your saved work','Select a project or its Overview, Contacts, Codes & standards, Sources, Activity or Chat with AI view; read authorities/questions on Overview, expand a brief or source excerpt, or open Supporting passage beside a chat claim.','The local app reads its database and renders saved findings, evidence labels, questions, costs and activity. Opening Chat alone does not send a model request.',local,none,`The project API returns at most ${n(F.sourceViewCharacters)} characters per source. Saved excerpts are not the whole original document. Activity is a view of recent events, not a full request transcript.`),
  row('U03','Connect your own account','Open API & spending, enter your key, choose Remember securely on this Windows account if wanted, and Save settings.','The app asks Anthropic for its model list before storing a new key. Requested model capabilities are checked separately before generation. Windows remembering protects the key for your OS account; elsewhere it stays in session memory. Saving requeues projects waiting for a key, which can start paid work.',`Your key authenticates a Models API request to ${F.hosts.anthropic}; the key-entry form reaches the local backend. No project prompt is sent by the key check itself. Requeued research sends the research payload described below.`, 'None for the key check; the research models above if queued work resumes.',`Key checks allow ${n(F.modelsPages)} pages of ${n(F.modelsPageSize)} models, each with a ${seconds(F.modelsTimeoutMs)}-second timeout. A failed key probe prevents saving that replacement. A connected badge does not certify your report or guarantee access to every future model.`),
  row('U04','Disconnect the key','Choose Disconnect & forget key.','The app clears its session key and removes the remembered credential file. Cached model availability is cleared. It does not cancel an already submitted request or delete your projects.',local,none,'Provider work already started may finish or be billed. Submitted data and saved reports remain. Put secrets only in the key field: arbitrary text pasted into project notes is not prevented from reaching a model.'),
  row('U05','Start research','Choose Research now or Research later, then Start research.','The app validates and saves inputs, queues jurisdiction research, then contacts and codes, an Opus evidence check, and an Opus final report. Contacts and codes can overlap after jurisdiction. It counts tokens, reserves an estimated pending cost, submits a stream or batch, executes allowed tool calls and validates the report. A batch result may lead to another submission.',researchSent,researchAI,researchBounds),
  row('U06','Continue, clarify or correct location','Choose Continue research or Review or extend report; add context, change address/site description or processing mode; confirm Continue.','Unsettled requests and active chat block the change. New context, changed location or pending answers reopen research; otherwise completed research can lead to another paid saved-evidence review. If the last final report was blocked by local report validation and nothing changed, its saved response is first rechecked under the current rules; a passing report is saved without a new request. Sources, earlier report and recorded charges remain. Corrected locations are also kept in Activity.',researchSent,researchAI,`A corrected address retains up to ${n(F.previousAddresses)} earlier addresses in project inputs. Resuming resets active time and applicable stage rounds, not accumulated source/search totals. It is a new paid round, not an undo or refund.`),
  row('U07','Research individual fire standards','Choose Research NFPA standards on an eligible fire protection project.','The local screening rules choose standards from discipline and project context. Completed jurisdiction/contact work is retained; codes, evidence check and report reopen. National Fire Protection Association (NFPA) targets are things to investigate, not a built-in adopted-edition list.',researchSent,researchAI,'Only eligible fire protection projects with completed initial jurisdiction and contacts can use this focused update. A grouped standard finding cannot fill the individual checklist. Unknown applicability or adoption evidence stays unresolved; retained sources and costs are not discarded.'),
  row('U08','Finish with what you have','Choose Finish with saved evidence.','Unfinished research stages become partial. The app queues a paid final report using saved material; a final report blocked only by local report validation is first rechecked from its saved response, without a new request. The final reviewer can look up saved excerpts but has no new web-research tool.',`Saved inputs, briefs, excerpts and saved-source lookup results go to ${F.hosts.anthropic}. This review does not fetch new public documents.`,`${opus}, medium effort, adaptive reasoning, up to ${n(F.research.reviewOutput)} output tokens; no temperature set.`,'This cannot be combined with a location correction or focused fire-standard update. Missing work is recorded in the report. A partial report is still billable generation.'),
  row('U09','Stop research','Choose Stop research and confirm Stop research.','The app sets a cancellation flag. New stages stop being scheduled. Already started reads finish saving, in-flight responses are recorded, and pending batches are checked and cancellation is attempted.',`Already sent prompts remain at Anthropic; batch status/results/cancel requests go to ${F.hosts.anthropic}. Already started source downloads may still complete.`,'No new research is deliberately queued by Stop; an in-flight model response or submitted batch may still run.','Cancel is not immediate termination or a refund. Completed usage is recorded; uncertain charges remain pending. Original batch outcomes still need reconciling.'),
  row('U10','Manage questions','Save answer, Edit answer, Dismiss, Reopen, or cancel editing.','Draft edits stay in the page. Save writes your response to the project database; dismissal changes its question status. Reopen makes it open again. These are your context and priorities, not a source-supported determination.',local,none,'Saving a question response uses a database transaction. It does not start research by itself. Reopening is not general undo and keeps the saved answer history field; errors leave the transaction unchanged.'),
  row('U11','Use your saved answers','Choose Research with saved answers and confirm.','The continuation path copies answered/dismissed question context into project inputs and reopens research. A dismissed question is a preference, not evidence that its requirement is inapplicable.',researchSent,researchAI,'Active/unsettled work blocks the continuation. The previous report remains until replaced; source/search totals and charges remain. New responses can be wrong even when they reflect your answer correctly.'),
  row('U12','Recover the original batch','In Activity, reconcile an uncertain batch using its batch ID.','The app reads the finished batch and its results, matches exact local request identifiers, then imports only matching attempts. It does not create a replacement batch.',`The batch ID goes to ${F.hosts.anthropic}; status and result data return to your local database.`, 'None newly submitted by reconciliation; applying a result can resume queued research models.','The batch must be finished and contain a matching request identifier; a mismatch changes no project state. Original completed work is charged. Imported results can queue later dependent stages.'),
  row('U13','Resolve an uncertain charge','In Activity, enter the confirmed charge and verification note, confirm the request ended or was canceled, and resolve it.','The app replaces the pending reservation with your entered amount and records how you say you checked it. It cannot independently read your invoice. Research remains paused for explicit continuation; an interrupted chat needs a new message.',local,none,`The accepted amount is $0–$${n(F.manualChargeMax)} per reconciliation. Confirm the original outcome in Anthropic Console first. Entering zero does not cancel a provider job or prove it was free.`),
  row('U14','Ask project chat','Open Chat with AI, choose Reply depth, type and Send message; Show earlier messages reads older history.','The app creates a reply with an identifier that prevents duplicate submission of the same message. It sends selected saved project evidence plus recent conversation, counts tokens, streams a response and executes allowed lookups in sequence. Pages read in chat join this project’s source register. Draft messages survive project switching in this page session.',chatSent,chatAI,chatBounds),
  row('U15','Retry a declined reply','Choose the suggested retry depth on a declined reply.','A new reply sends the same user question with the selected depth. The app reuses the retry submission identifier if a local response was lost. A model refusal does not mean a paid request never happened.',chatSent,chatAI,'Retry requires your click; it is not automatic on reload. Refused replies discard partial displayed answer/proposals but preserve recorded usage and cost. The ordinary chat bounds apply again to this new reply.'),
  row('U16','Stop the reply','Choose Stop reply.','The app sets a stop flag and waits for the current model request to finish so its result and usage can be recorded. No later local lookups or model rounds are deliberately started for that reply.',`The existing request is already at ${F.hosts.anthropic}. An in-flight source read may complete. The Stop action itself is a local request.`, 'The currently running chat model may finish; no new reply is submitted by Stop.','A completed response may be saved; an uncertain stream keeps its reservation. Stop is not a refund and does not abort the vendor stream immediately.'),
  row('U17','Apply a chat proposal','Choose Apply or Apply and start research on a proposal; select processing mode for paid research.','The app validates the saved proposal against the current project. Answer/dismiss proposals use the question-save path; research/location proposals use the same continuation path as the dialog. Repeated Apply is refused. Paid proposals become stale if research has run since they were made.', 'An answer/dismissal is local. Applying research or a location change sends the research payload when the queued work starts.', 'None to apply an answer/dismissal. Paid research uses the research models/settings above.',`Chat may save up to ${n(F.chat.proposals)} proposals, after at most ${n(F.chat.proposalCalls)} proposal-tool calls per reply. An approved model suggestion is stored as user context, not verified evidence. Paid proposals wait for settled work; approval is recorded before continuation, and validation failure can restore the proposal when the project has not changed.`),
  row('U18','Export your research','Choose Export PDF, Excel workbook or JSON.','The local app reads saved inputs, report, question responses, stage briefs and sources, then creates the file using local export libraries. It does not send the report to an online converter.',local,none,`Each exported source excerpt is capped at ${n(F.exportCharacters)} characters. JSON is a research record, not a full backup: it omits chat history and raw request/tool transcripts. Export can work before research is complete; the limitations remain visible. There is no generic JSON-import command.`),
  row('U19','Save or cancel a desktop export','Choose a filename in the desktop Save dialog, or Cancel.','The desktop first stages the local download in a temporary folder, then copies it to your selected file. It checks the extension and refuses to overwrite an existing file. Temporary staging is removed after the operation.',local,none,'Canceling the file save does not cancel research or erase the database. A failed/canceled export leaves project data and costs unchanged.'),
  row('U20','Inspect diagnostics','Open API & spending → Diagnostics; select records, Refresh or Download diagnostics.','The app builds a local summary of attempts, models/settings, usage, request/batch identifiers, stages and recent events. Sensitive field names and recognizable credentials are filtered. Location/progress event text is omitted from that download.',local,none,`Up to ${n(F.diagnosticEvents)} detailed events are retained across the workspace. Request summaries do not contain prompts/source text, but errors and notes may contain source or personal details. Review before sharing. The app does not upload the download automatically; the raw database is more sensitive.`),
  row('U21','Check for an update','In the packaged desktop, choose Check for updates.','The app fetches latest published release metadata, checks version format and expected installer/checksum filenames, and saves the result. The forced check bypasses the ordinary cooldown. It offers a release link; it does not install an update.',`A release lookup goes to ${F.hosts.updates}, with the app version in its User-Agent. No project payload is placed in that request.`,none,`A ${seconds(F.updateTimeoutMs)}-second timeout reports an unavailable check rather than blocking research. This control is absent from the source server by default. Filename checks are not installer signature verification.`),
  row('U22','Read help and close a dialog','Choose User guide, About, the full license, Why trust it?, or the dossier button; use Back, Close or Escape.','The app loads local help/assets or the local license text. The trust topic opens as a dialog; the dossier stacks above it. Its contents links navigate sections without hiding them. Closing the dossier returns you to the topic button.',local,none,'The top dialog contains keyboard focus; Escape closes one level. Reading help does not run a model or cancel existing background work. The further-reading links below are external only if you activate them.'),
  row('U23','Follow an external link','Open a source, authority website, contact link, author link, release link or Further reading.','The web UI delegates links to your browser or mail/phone handler. The desktop validates public HTTP/HTTPS links before opening your system browser; other schemes are denied there. Your external browser has its own cookies, history and network behavior.', 'The destination URL goes to its host; opening a contact handler can start a separate app. The local server sets a no-referrer policy. This app does not send an email or call on your behalf.',none,'A linked site can make additional connections, require authentication or change its content. Desktop link validation is not a guarantee about later redirects or activity in your external browser.'),
  row('U24','Delete a project','Choose Delete project and confirm.','A database transaction removes that project’s report, source rows, answers, chat, attempts and project-specific diagnostics. Anonymous recorded-charge rows stay in workspace spending totals.',local,none,'Active, received or uncertain requests block deletion until they finish or are resolved. There is no undo. Logical row deletion is not a secure wipe of database journal pages, backups, exported files or provider-held data.'),
  row('U25','Start or close the app','Use the source launch/stop commands, close the desktop window, or choose Keep open / Close AHJ Atlas when work is active.','The source launcher starts a detached local backend and writes a local server log; closing its browser leaves that backend running. The stop command drains local active work. The desktop owns its backend and confirms closing during active work, then drains it. Submitted batches can continue at Anthropic.', 'Startup itself is local, with the key/update/recovered-work exceptions in the automatic cards. Shutting down can leave existing provider work running.', 'None just to launch/close; recovered or already submitted research can involve the research models.',`The source default is ${F.serverHost}:${n(F.serverPort).replace(/,/g,'')}; ATLAS_PORT and ATLAS_DATA_DIR override it. The desktop chooses a loopback port; development profile/data overrides are ATLAS_DESKTOP_PROFILE_DIR and ATLAS_DESKTOP_DATA_DIR. Shutdown waits for active local work; it has no independent hard drain timeout and is not batch cancellation.`),
  row('U26','Import an old source workspace','At the initial desktop prompt, choose Import existing workspace, select a source/data folder, Start fresh, or Quit.','The desktop checks the old database, creates a consistent backup/copy, removes an inappropriate stale destination instance lock, and records its migration decision. The source workspace remains available; stored local key protection is handled separately.',local,none,'This is a startup migration, not arbitrary file import. An initialized destination is not silently overwritten. Cancellation/failure prevents that launch; keep the preserved source folder as your backup.'),
  row('A01','Recover saved work at startup','You reopen the app; no new research button is required for work already queued.','The store opens its database and applies schema migrations. Interrupted submissions become uncertain, received outcomes are applied, queued research can advance when a key is available, and pending batches are polled. Interrupted chat becomes complete, attention or interrupted from saved records; it is not automatically resubmitted.', 'Schema recovery is local. Resumed research, key checks and batch reads use Anthropic as described above.', 'Research models for resumed queued stages; None for database recovery or reconstructing saved chat.','Existing canceled/complete/attention states are not ordinary auto-start targets. A formerly retired spending-limit pause requires explicit continuation. Unknown outcomes retain reservations rather than being automatically duplicated.'),
  row('A02','Advance and retry research','A research round you started is still active.','The worker advances dependencies and model tool follow-ups. Adjacent source reads run in groups; other tool results preserve order. Text-only incomplete stages get bounded coverage follow-ups; output truncation queues a compact recovery. A completion brief rejected on a stage’s last allowed request is kept as unverified leads and the stage becomes partial. Known transient rejected research requests can retry after a delay. Chat failures are not retried this way.',researchSent,researchAI,`Worker checks every ${seconds(F.workerMs)} second; ${n(F.researchWorkers)} research slots, up to ${n(F.parallelReads)} concurrent reads per group. At most ${n(F.retries)} transient-error retries for a stage, counted against its recorded errored attempts; earlier errors can reduce that allowance. Delays start at ${seconds(F.retryBaseMs)} seconds and increase or honor the provider’s delay. At most ${n(F.research.continuations)} coverage follow-ups and ${n(F.outputRecoveries)} truncated-output recovery per stage, within its request cap. After ${n(F.research.contextResets)} context resets, non-final stages switch to completion-only requests. Already received responses remain billable.`),
  row('A03','Poll submitted batches','A submitted batch remains outstanding, even after Cancel or an app restart.','The worker asks for status, then downloads results when finished. A canceled project also attempts provider cancellation. Transient retrieval failures defer the next poll; polling is not a new paid replacement submission.',`Batch identifiers, status/result reads and cancellation requests go to ${F.hosts.anthropic}.`, 'The already submitted model job may still execute at Anthropic; no new model solely for polling.',`Ordinary polls are ${seconds(F.pollMs)} seconds apart; retrieval failures delay further. There is no small fixed poll-retry count. Automatic retrieval stops after ${n(F.research.batchRetentionMs/86400000)} days from the local attempt’s creation and marks the outcome uncertain. This local policy does not prove the vendor’s retention policy or cancel its job.`),
  row('A04','Check a remembered key','You start with a remembered Windows key, or a visible app has an unavailable connection.','Startup checks the model list. The visible UI retries temporarily unavailable checks with backoff; a later unauthorized provider request also disconnects the badge. Status results are ordered so an older successful request cannot override a newer rejection.',`The key authenticates requests to ${F.hosts.anthropic}. The model-list check itself sends no project prompt.`,none,`Unavailable-key retries start after ${minutes(F.keyRetryStartMs)} minute and back off to ${minutes(F.keyRetryMaxMs)} minutes while the UI is visible. No finite total retry count is enforced. A missing/rejected key is not silently invented; per-request model checks remain necessary.`),
  row('A05','Look for desktop releases','You open a packaged desktop window, return to it, or its update timer fires.','The UI triggers a release check on startup, visibility changes and its timer. A persisted cooldown limits actual external requests unless you force a check. Source-server and development-desktop startup do not create this updater by default.',`The release metadata request goes to ${F.hosts.updates}, with app version in its User-Agent and no constructed project payload.`,none,`UI timer: ${n(F.updateUiMs/3600000)} hour. External checks normally no more often than ${n(F.updateIntervalMs/3600000)} hours per saved attempt; failure is cached too. No automatic download or installation is implemented.`),
  row('A06','Save and refresh locally','The app is open; you navigate, draft a message, a reply streams, or a browser error occurs.','The visible UI refreshes saved project/connection status, follows active chat drafts, and sends bounded browser errors to its local diagnostics route. Database writes persist research and replies; unsent chat/question drafts stay in page memory. No outbound analytics uploader is implemented.',local,none,`Ordinary visible refresh: ${seconds(F.uiRefreshMs)} seconds; active visible chat refresh: ${seconds(F.chatRefreshMs)} second. These are local requests, not new model calls, except the explicitly described key/update checks. Closing/reloading the page can lose unsent drafts. Detailed events rotate at ${n(F.diagnosticEvents)} records; saved project content has no age-based expiry.`),
];
export const SHORT_POINTS=[
  ['C01','You review findings before using them','Reports include evidence labels and questions to resolve. They are research assistance, not a determination that your design complies.'],
  ['C02','Sources and guesses have different roles','Retrieved passages carry source IDs; search leads and your answers have separate roles. Chat is instructed to label general knowledge, but that instruction is not a guarantee.'],
  ['C03','Quotation checks can expose missing support','The app demotes a “verified” entry without a matching retrieved quote and adds gaps. A jurisdiction finding the final review omitted stays unverified. A matching quote still needs your check for scope, date and legal meaning.'],
  ['C05','Proposed project edits wait for you','Chat saves proposal cards; Apply is the route that changes answers or starts proposed research. Chat can already add sources and incur costs while answering.'],
  ['C14','Started work can continue without clicks','Queued stages, retries and batches advance automatically. Startup key checks, unavailable-key retries, desktop release checks and local refreshes also run without a new click.'],
  ['C06','Your project crosses a named boundary','Prompts and evidence go to Anthropic. Source URLs go to public sites; optional US geocoding sends the address to Census. Desktop update checks go to GitHub.'],
  ['C15','Your key and costs need attention','Keys stay in session memory unless Windows remembering protects them for your account. Costs are estimates, there is no app spend cap, and Stop can still leave billed work.'],
];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=text=>`<p>${esc(text)}</p>`;
const note=(title,text)=>`<aside class="trust-note"><h3>${esc(title)}</h3>${p(text)}</aside>`;
const table=(headers,rows)=>`<div class="trust-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const contrast=(left,right)=>`<div class="trust-contrast"><div><h3>Leaves your machine</h3>${left.map(p).join('')}</div><div><h3>Stays on your machine</h3>${right.map(p).join('')}</div></div>`;
const list=items=>`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const section=(id,kicker,title,claim,body)=>({id,kicker,title,claim,body});
export function runtimeCard(x,index){return `<article class="trust-runtime" id="trust-${x.id}" data-claim="${x.id}"><h3><span aria-hidden="true">${index+1}. </span>${esc(x.title)}</h3><dl>${[['You do',x.you],['What runs',x.runs],['What is sent',x.sent],['AI involved',x.ai],['Bounded by',x.bounds]].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></article>`;}
