export const SECTIONS=[
  section('answer','Start here','The short answer','C01',
    `<p><strong>Your evidence remains inspectable.</strong> You can compare source passages, evidence labels and unresolved questions. Model prose and your own answers are not independent proof.</p><p><strong>Automation has an explicit scope.</strong> Starting a round authorizes its dependent stages and tool calls. The automatic cards below name recovery, retries, polling, key checks, release checks and local persistence.</p><p><strong>Checks can be inspected; judgments need review.</strong> You can reproduce quotation matching, bounds and cost arithmetic from saved records. You cannot reliably re-create a model’s legal interpretation, or assume another run produces the same answer.</p>`),
  section('origins','Provenance','Where your findings come from','C02 C19',table(['Origin','What it actually is','How you can tell'],[
    ['You','Address, scope, building use, dates, notes, answers and dismissals; applied chat suggestions become user context.','Project context and Questions show your saved responses. Approval is not independent verification.'],
    ['Public documents','Text retrieved from a public webpage/PDF, rendered text, or US Census response.','Sources show IDs, URLs, retrieval dates, reading method and available text. “Read as evidence” does not mean the entire document was read.'],
    ['Search leads','Vendor search results and citation URLs awaiting a document read.','Discovery records do not provide retrieved-text evidence.'],
    ['Built-in rules','Stage assignments, local NFPA screening, schema and quote checks, templates and cost arithmetic.','The fire checklist has no built-in adopted-edition list. Reports can include unresolved rows generated by validation.'],
    ['The model','Research briefs, conclusions, summaries, proposed edits, chat answers and optional general professional knowledge.','Evidence status and citations help review. Chat is instructed to label general knowledge; unlabelled prose is not automatically detected.']
  ])+note('Things that are not happening','There is no implemented hidden local reference corpus, local model training job, cross-project chat lookup or team synchronization service. The model can still draw on its learned knowledge. The app has no training/fine-tuning API path; that does not establish what Anthropic retains or how its vendor terms apply. Check the current policies below.')),
  section('engine','The engine','What actually does the work','C04',p('Effort is the model’s reasoning setting, not a quality certificate. Adaptive reasoning lets the model decide how much internal reasoning to use. Research later submits a batch: a vendor-queued job that runs later. Research now and chat receive a stream: a response delivered as it is generated.')+table(['Job','Model or component','Why'],[
    ...F.stages.map(s=>[s.label,`${F.models[s.model].id}; ${s.effort} effort; Anthropic servers`,s.id==='review'?'Build a structured report from saved evidence; saved-source lookups only.':s.id==='verification'?'Compare earlier findings against evidence; same vendor/model family, not an independent legal authority.':'Generate research/tool requests for this assigned topic.']),
    ...Object.entries(F.modes).map(([,m])=>[`${m.label} project chat`,`${F.models[m.modelKey].id}; ${m.effort} effort; Anthropic servers`,'Answer from selected saved records and permitted lookups; propose edits for your approval.']),
    ['Reading, validation and export','Node.js, PDF.js, canvas, PDFKit, ExcelJS and optional installed Chromium-family browser; your computer','Parse text/images, execute constrained reads, check quotations, store records and create files locally.']
  ])+p(researchAI)+p(chatAI)+p(`A token is a unit of text processed by the vendor; it is not a character or a word. Research input is capped at ${n(F.research.input)} counted tokens; large contexts are rebuilt from checkpoints starting at ${n(F.research.checkpointInput)}. Chat input is at most ${n(F.chat.input)} tokens and may be lower based on the model’s reported window minus its output allowance. Research cache lifetime is ${F.realtimeCacheTTL} in real time and ${F.batchCacheTTL} in batch; chat cache lifetime is ${F.chat.cacheTTL}. Cache writes and reads can affect charges; a hit is not guaranteed.`)),
  section('boundary','The boundary','What leaves your computer, and where','C06',DIAGRAM+contrast([
    `${F.hosts.anthropic}: Models API authentication; counted/generated request context, selected project evidence, questions and chat; returned tool text and optional PDF images. Native web search runs at the vendor using model-written queries.`,
    `${F.hosts.census}: the project address in a URL when the optional US address tool is called.`,
    'Public source hosts and redirects: requested URLs and request headers. The optional renderer also fetches permitted scripts, styles, images and GET-based page data. Public URLs/queries can reveal project information; research has a weaker URL-origin restriction than chat.',
    `${F.hosts.updates}: packaged-desktop release metadata check, automatically or when forced; the app version is in its User-Agent.`,
    'External source, website, release, author and further-reading links: only when you follow them. They open in your browser, which can use its own accounts/cookies and make additional connections. DNS lookups and normal network routing also reveal destinations.'
  ],[
    'The working database, full saved request/response and tool records, selected sources, chat history, events and estimated costs. Selected portions of these also go to the model when you research/chat.',
    'Session key in memory; Windows-protected credential file if you choose remembering. The key also authenticates vendor requests; it is not intentionally placed in the constructed project prompt.',
    'PDF/Excel/JSON export generation and diagnostic preparation. Sharing these files is a separate action you take.',
    'The page and its assets are served through local HTTP on loopback. This is still network traffic between local processes. Trust assets use no external scripts, fonts, images or analytics.'
  ])+note('There is no blanket “nothing leaves” promise','Source reads permit HTTP as well as HTTPS. The app cannot control vendor-side search traffic or every network action of your external browser/Chromium platform. Do not put confidential information in a project if your policy forbids sending selected context to Anthropic or data-bearing URLs to public sites.')),
  section('runtime','Runtime','What runs for each action','C12 C13 C14',p('Each card uses the same rows. Pure navigation and file operations are included so you can tell local work from generation. Started rounds include later dependent work without another click.')+RUNTIME.map(runtimeCard).join('')),
  section('tools','Blast radius','What the AI may touch','C05 C10',table(['Tool or capability','What it can do','Constraint'],[
    ['Native web_search','Ask the vendor to search public sources.','Per-request and project/reply search allowances. Searches return discovery leads; queries are model-written and may contain project details. The app does not inspect vendor-side traffic.'],
    ['read_source','Fetch public text/PDF and save excerpts.','Public HTTP/HTTPS, standard ports, DNS/IP checks and pinned resolution; each redirect checked. Chat additionally requires a URL from its sources/known links/search results/user message; research does not impose that provenance gate.'],
    ['render_page','Run page JavaScript in a fresh installed browser profile and collect text/links.','No existing sign-ins; GET/HEAD resources mediated through public fetch. Forms that require POST, subframes, media, fonts, WebSocket, WebTransport, peer connections and workers are blocked by the implemented interception/API guards. Public GET calls can still disclose information.'],
    ['inspect_pdf','Turn one requested page into an image for the next model request.','Scanned-image readings are not machine-readable quotation proof. Page image may be sent to Anthropic.'],
    ['locate_address','Request US Census address geographies.','Reads the current project address; other countries get a local explanatory result. Geography does not establish regulatory authority.'],
    ['read_saved_source / read_project / find_project_sources','Read/search bounded records selected by the server.','Chat is bound to the current project; the model cannot select a different project ID or arbitrary file. Final-report review has only read_saved_source.'],
    ['save_progress / finish_research','Save a brief/checkpoint and declare coverage.','Coverage schema and required areas are checked; declarations can record unresolved work. They are not legal certification.'],
    ['Proposal tools','Save answer/dismissal, research or location-change cards.','The model cannot invoke the Apply route. User Apply validates current state and starts a paid round only for paid proposals.']
  ])+p(`Source fetches allow at most ${n(F.research.documentBytes/1048576)} MiB per document and ${n(F.redirects)} redirects, with a ${seconds(F.sourceIdleMs)}-second socket-idle timeout, not a total deadline. Reads return ${n(F.research.readChars)} characters by default, at most ${n(F.research.pageChars)}; PDF text reads default to ${n(F.pdfDefaultPages)} page, allow ${n(F.pdfMaxPages)} pages per range or search up to ${n(F.pdfSearchPages)} pages, starting no later than page ${n(F.pdfMaxPage)}.`)+p(`The renderer allows ${n(F.renderRequests)} counted requests, with ${n(F.renderBytes/1048576)} MiB per fetched resource; data URLs bypass that count. ATLAS_BROWSER can select the installed browser executable. Browser launch allows ${seconds(F.renderStartMs)} seconds, navigation ${seconds(F.renderNavigationMs)} seconds, and idle waiting ${seconds(F.renderWaitMs)} seconds with an idle period of ${n(F.renderIdleMs)} milliseconds. These are default code-level controls, not user-adjustable UI settings. These controls limit a particular read; they are not a guarantee of perfectly bounded CPU time or no background browser networking.`)+note('Capabilities it is not given','The model has no general command runner, filesystem browser, key-reading tool, email-sending tool, account-login tool, permit-submission tool or payment tool. The local app itself writes files, starts the renderer and uses your key for HTTPS requests. A limited tool list does not eliminate prompt injection or stop a permitted URL/query from leaking data.')),
  section('terms','Exact words','What the trust labels mean','C03',
    note('Verified — the exact claim',`A model labels the finding, and local validation requires at least one quotation of ${n(F.quoteMin)} normalized characters to occur in retrieved source text. Matching ignores letter case and repeated whitespace; displayed quotations are capped at ${n(F.quoteMax)} characters and page/section labels at ${n(F.pageSectionMax)}. Unsupported “verified” entries are demoted. NFPA edition rows also require adoption/edition source links and designation/year checks.`)+p('It does NOT prove every field is supported, the quote is legally controlling, the address is correct, or all exceptions were read. Ordinary code rows have weaker edition-specific checks than NFPA rows. A model can confidently misinterpret a real passage.')+
    note('Reviewed — the exact claim','An Opus evidence stage checks earlier findings, and an Opus final report reviews selected saved evidence. Local validation checks report shape, quotations, known URLs, published-email presence and missing work. An omitted jurisdiction or coverage row is rebuilt as unverified from research-stage records and listed as a question.')+p('It does NOT mean a human reviewed the result or a different vendor independently agreed. The two reviews can share the same mistaken interpretation.')+
    note('Approved — the exact claim','You applied a saved proposal through the UI. The app records your action, validates its current project and uses the ordinary save/continue paths.')+p('It does NOT make a suggested answer independent source evidence, obtain authority approval or certify applicability.')+
    note('Connected — the exact claim','Anthropic accepted a key-check or authorized request; new generation checks the requested model’s available capabilities.')+p('It does NOT promise future availability, spending allowance or successful research. A badge is an account-connection status, not a quality rating.')+
    note('Read as evidence — the exact claim','Source text was retrieved and saved. Discovery-only results and visual-only PDF inspections are distinguished.')+p('It does NOT mean the whole document was read. Page ranges, excerpts and source caps can omit the decisive exception. “No match” in saved text is not “no requirement.”')),
  section('local','No AI here','The work done without a model','C16',list([
    'Project form validation, navigation, question saving/dismissal/reopening and deletion guards.',
    'Database transactions, request identifiers, cancellation flags, tool admission and source/search accounting.',
    'Text/PDF extraction, exact-passage selection and normalized quotation matching. A source fetch is still network work; a PDF-image interpretation is still a model task.',
    'NFPA screening rules and missing-checklist guards; a screening target is not an adopted edition.',
    'Known-link filtering, contact-email presence checks, HTML/Markdown rendering and local security checks.',
    'PDF, Excel and JSON generation; diagnostic summaries/redaction; dollar estimates from usage.',
    'Local startup checks, workspace copying and key protection. Remote key/update status checks use network but no model generation.'
  ])+note('When the network is disconnected','You can read already saved findings/sources/chat, manage question responses, inspect diagnostics, delete eligible settled projects and export saved research. New research/chat, remote pages, model-list checks and release lookups need connectivity. The local backend must still be running.')),
  section('security','Protection','Security and privacy mechanisms','C07 C08 C09 C11',table(['Concern','How it is handled'],[
    ['Credential storage','Session memory by default. Windows Remember uses Data Protection API (DPAPI), an OS service tied to your signed-in account, through PowerShell; credential.bin holds protected bytes. Other systems have no supported persistent protected-key path. Same-account processes may still be able to decrypt/access it.'],
    ['Local exposure',`The backend binds ${F.serverHost}, checks Host/Origin, requires a random X-App-Token for mutations, and caps request bodies at ${n(F.requestBytes)} bytes. This is a cross-site request guard, not a login system against other local processes. The bootstrap token is accessible locally.`],
    ['Page and desktop isolation','Content Security Policy restricts app scripts/assets to the local origin and blocks framing; app text is escaped and Markdown is locally rendered. Desktop disables Node access in the page, separates its context, enables the renderer sandbox and denies requested permissions. Desktop developer tools are gated in packaged builds.'],
    ['Untrusted evidence','Prompts treat retrieved text as data; tools enforce capabilities separately. This reduces scope, not the chance of every persuasive instruction or false legal conclusion. Research URLs remain model-chosen public addresses.'],
    ['Stored project privacy','Source-server default: checkout/data/atlas.sqlite; packaged Windows default: %LOCALAPPDATA%/AHJ Atlas/data/atlas.sqlite (with appData fallback); development desktop uses a temporary AHJ Atlas Desktop Dev profile. SQLite is a readable database format, not a plain-text document; JSON fields hold inputs, prompts, responses and tool results. The app does not encrypt this database. OS permissions and your backup policy matter.'],
    ['Retention and caches',`Project records have no age purge. Saved source text is capped at ${n(F.sourceCharacters)} characters per URL; merging can discard older saved text at that cap. The download cache is memory-only, up to ${n(F.cacheDocuments)} documents for ${minutes(F.cacheMs)} minutes. Renderer temporary profiles are cleaned after a read. Diagnostics rotate at ${n(F.diagnosticEvents)} events. Source launcher data/server.log has no rotation policy in the launcher.`],
    ['Other local files','SQLite uses a write-ahead journal (WAL), which keeps database updates in companion files. Desktop stores window-state.json, update-check.json and migration-decision.json; migration can retain backup material. Windows credential.bin is outside the data subfolder. Exports go where you save them; uninstall keeps app data. A copied database/export is not made safe by deleting its project later.'],
    ['Diagnostic sharing','Recognizable key/token fields are removed or redacted; request summaries omit prompts and source text. Error notes may still contain personal/source details. No diagnostic upload endpoint is implemented; inspect the file before you send it elsewhere. Raw request records in SQLite are not similarly minimized.']
  ])+p('Your API key is not deliberately inserted into constructed prompts or report exports. That does not detect arbitrary secrets you type into notes, a chat message or a source URL. Forgetting the key cannot recall prior requests from a vendor.')),
  section('money','Money','Who charges you and what the meter means','C15',p('Anthropic bills your API account. The app has no hard spending limit. Request counts, source limits and time allowances bound work, not dollars; a stopped, failed or refused response can still have chargeable completed usage.')+
    table(['Item','Local calculation','What you can rely on'],[
      ...Object.values(F.models).map(m=>[m.id,`Per ${n(F.million)} tokens: input $${m.input}, output $${m.output}, cache read $${m.cacheRead}.`,'These are embedded list-price estimates, not invoice lookups.']),
      ['Cache writes','Short-lifetime creation uses a markup over input price; hour-long creation uses the configured longer-lifetime rate. Separate vendor counters determine writes/reads.','An hour cache lifetime is not a guarantee of a cache hit or an hour-long retention limit for all provider data.'],
      ['Native web search',`$${F.searchPrice} per ${n(F.searchUnit)} searches, plus tokens used by results.`,'Returned search counts enter the local arithmetic.'],
      ['Batch model tokens',`${n(F.batchFactor*100)}% of real-time token prices in the app estimate; search fees unchanged.`,'A batch can require multiple dependent submissions.'],
      ['Pending','A conservative estimate from counted input, allowed output and possible search use is reserved before submission.','Reservation is not a vendor authorization hold or spend cap; it remains when an outcome is ambiguous.'],
      ['Recorded','Returned token/search usage is multiplied by embedded rates; manual reconciliation uses your entered amount.','Usage counters are what the provider returned. Dollar figures are estimates, even fields internally named actual. Deleted projects keep anonymous recorded amounts in workspace totals.']
    ])+p(`The embedded price date is ${F.priceDate}. Short-lifetime cache creation is priced at ${n(F.shortCacheFactor)} times input and hour-long creation at ${n(F.longCacheFactor)} times input in the current calculator. Compare recorded request IDs and your Anthropic Console, including discounts/taxes/account terms that this meter does not fetch.`)+note('Failure is not a refund','The app disables SDK automatic message retries. It can retry known transient rejected research requests within stage bounds; it preserves ambiguous POST/stream outcomes rather than replaying them. A completed response that fails local validation still has usage recorded. Stopping waits for work already started; submitted batches can complete after exit. Resolve uncertain work using the original request/batch before starting a replacement.')),
  section('limits','Honesty','What this does not do','C17',list([
    'It does not certify jurisdiction, code compliance, permit acceptance or a published contact’s current role. Mailing city and Census geography are not regulatory authority; confirm with the responsible office.',
    'It does not prove completeness. Source access restrictions, excerpt/page caps, unread amendments, stale documents and old saved addresses can omit the deciding fact. Check current adoption instruments, transition rules and exceptions.',
    'It does not turn an exact text match into legal meaning. NFPA checks reduce nearby-year mistakes but cannot prove an adoption chain applies to your scope. Generic code rows and narrative summaries need your own review.',
    'It does not guarantee the model labels every inference or uses only sources. Instructions and citations are fallible; learned general knowledge can appear in prose. Cross-check high-consequence claims directly.',
    'It does not protect data from every local process, encrypt your whole workspace, securely erase all copies, set a hard spend cap, or control vendor privacy/retention terms.',
    'It does not send permit applications, emails or payments through a model tool. Following an external link opens a separate browser/handler with its own behavior.',
    'It does not guarantee repeatable model answers or a final answer within a strict wall-clock limit. Source socket timeouts measure inactivity, and shutdown waits for local active work without its own hard timeout.',
    'It does not auto-install updates or prove publisher identity from release filenames/checksums. The Windows build configuration permits unsigned installers; compare published hashes and follow your installation policy.'
  ])+p(`Provider requests normally allow ${seconds(F.providerRequestMs)} seconds; message streams have a ${minutes(F.providerStreamMs)}-minute whole-stream ceiling. Token counts use ${seconds(F.tokenCountMs)} seconds; batch submit/status/results/cancel calls use ${seconds(F.batchSubmitMs)}/${seconds(F.batchPollMs)}/${seconds(F.batchResultsMs)}/${seconds(F.batchCancelMs)} seconds respectively. Those limits do not make an incomplete outcome free or justify replaying it.`)),
  section('audit','The point','Check it yourself','C18',`<ol class="trust-audit">${[
    'Open Sources and compare a quoted passage with its original document. You will see the URL, retrieval method/date and excerpt. Check its scope, adopted edition, effective date and exceptions, not just a familiar year.',
    'Read Questions and evidence labels. You will see missing applicability and incomplete-stage work; an answered or dismissed question is marked as your response, not independent evidence.',
    'Open Activity. You will see stage starts, source reads, follow-ups, cancellation/recovery notes and recorded costs. It is a recent event view, not the full prompt transcript.',
    'Open API & spending → Diagnostics, Refresh, then Download diagnostics. You will see request/batch IDs, model/settings summaries, usage counters and failures. It omits project prompts/source text, but inspect errors before sharing.',
    'Export JSON and open it in a text editor. You will see project context, report, questions, stage briefs and capped source excerpts. You will not see chat or full request records there; keep a separate workspace backup if you need them.',
    'Compare request identifiers, returned usage and pending work with Anthropic Console. You will see whether the local list-price estimate agrees with your account’s actual billing; confirm original uncertain jobs before resolving or retrying.',
    'Disconnect your network while leaving the backend running. Saved records and exports remain usable; new model/source/key/update requests fail or wait. Existing submitted batch work can still run at the provider.',
    'Use your organization’s network monitor for a controlled synthetic project. Expect the Anthropic API, chosen public source hosts, optional Census and packaged GitHub checks, plus DNS and any external-browser traffic. URLs and search queries can reveal details. Do not capture/share a real key or confidential prompt.',
    'For a deeper local audit, close the app and preserve its complete data folder and companion journal files. Open a copied atlas.sqlite with a SQLite viewer. You will find raw attempts, payloads, responses, tool results and chat beyond the JSON export. These contain sensitive text; use a disposable synthetic project and review implementation/tests if you need to re-derive checks.'
  ].map(x=>`<li>${esc(x)}</li>`).join('')}</ol><aside class="trust-note trust-reading"><h3>Further reading</h3><ul>${[
    ['https://privacy.claude.com/','Anthropic privacy policies and data handling'],
    ['https://trust.anthropic.com/','Anthropic Trust Center'],
    ['https://platform.claude.com/docs/en/build-with-claude/batch-processing','Batch processing and retention documentation'],
    ['https://platform.claude.com/docs/en/about-claude/pricing','Current API pricing'],
    ['https://platform.claude.com/docs/en/build-with-claude/prompt-caching','Prompt caching'],
    ['https://github.com/Abe-Borg/ahj-atlas/releases','AHJ Atlas releases and published checksums']
  ].map(([href,label])=>`<li><a href="${href}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a></li>`).join('')}</ul></aside>`+note('Still not convinced?','Good. Use the app skeptically: start with a synthetic or low-consequence project, inspect original passages, compare charges, and ask the responsible authority to resolve gaps. Treat the model as a research assistant whose work you check, not the person who signs your design. Vendor policy links describe vendor commitments; this app cannot enforce them.')),
];
export function shortHTML(){return `<div class="dialog-heading"><div><span class="eyebrow">YOUR GUIDE TO THE EVIDENCE</span><h2 id="trust-topic-title" tabindex="-1">Why trust it?</h2></div><button type="button" class="icon-button" data-trust-close aria-label="Close trust topic">×</button></div><p>AHJ Atlas gives you evidence and questions to inspect before you rely on a finding; your professional review remains the deciding step.</p><div class="trust-points">${SHORT_POINTS.map(([id,title,text])=>`<article data-claim="${id}"><h3>${esc(title)}</h3>${p(text)}</article>`).join('')}</div><aside class="trust-note"><h3>Not convinced?</h3><p>Fair. The points above are claims — here is the mechanism behind each one, action by action, plus how to audit any of it yourself.</p><button type="button" class="button primary" id="trust-show-dossier">I'm not convinced — show me exactly what runs →</button></aside>`;}
export function dossierHTML(){return `<div class="dialog-heading"><div><span class="eyebrow">THE MECHANISMS, ACTION BY ACTION</span><h2 id="trust-dossier-title" tabindex="-1">I'm not convinced</h2><p class="muted">AHJ Atlas · for the person putting their name on the output</p></div><button type="button" class="icon-button" data-trust-close aria-label="Close dossier">×</button></div><div class="trust-layout"><nav class="trust-contents" aria-label="Dossier contents">${SECTIONS.map(s=>`<a href="#trust-${s.id}">${esc(s.title)}</a>`).join('')}</nav><div class="trust-body">${SECTIONS.map(s=>`<section id="trust-${s.id}" data-claim="${s.claim}" class="trust-section" aria-labelledby="trust-heading-${s.id}"><span class="eyebrow">${esc(s.kicker)}</span><h2 id="trust-heading-${s.id}">${esc(s.title)}</h2>${s.body}</section>`).join('')}<button type="button" class="button secondary" data-trust-close>Back to Why trust it?</button></div></div>`;}
export function mountTrust(root=document){
  if(root.getElementById('trust-topic'))return;
  const topic=root.createElement('dialog'),dossier=root.createElement('dialog');
  topic.id='trust-topic';topic.className='trust-dialog trust-topic';topic.setAttribute('aria-labelledby','trust-topic-title');topic.innerHTML=shortHTML();
  dossier.id='trust-dossier';dossier.className='trust-dialog trust-dossier';dossier.setAttribute('aria-labelledby','trust-dossier-title');dossier.innerHTML=dossierHTML();
  root.body.append(topic,dossier);
  let opener=null;
  const show=(dialog,button)=>{opener=button;dialog.showModal();dialog.querySelector('h2').focus();};
  root.querySelectorAll('[data-open-trust]').forEach(button=>button.addEventListener('click',()=>show(topic,button)));
  const more=topic.querySelector('#trust-show-dossier');
  more.addEventListener('click',()=>{dossier.showModal();dossier.scrollTop=0;dossier.querySelector('h2').focus();highlight();});
  topic.addEventListener('close',()=>opener?.focus());
  dossier.addEventListener('close',()=>more.focus());
  for(const dialog of [topic,dossier]){
    dialog.querySelectorAll('[data-trust-close]').forEach(button=>button.addEventListener('click',()=>dialog.close()));
    // Consume the top layer's Escape so a single key cannot close its parent too.
    dialog.addEventListener('cancel',event=>{event.preventDefault();event.stopPropagation();dialog.close();});
    dialog.addEventListener('keydown',event=>{
      if(event.key!=='Tab')return;
      const focusable=[...dialog.querySelectorAll('button,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);
      const first=focusable[0],last=focusable.at(-1),active=root.activeElement;
      if(event.shiftKey&&(active===first||!focusable.includes(active))){event.preventDefault();last?.focus();}
      else if(!event.shiftKey&&(active===last||!focusable.includes(active))){event.preventDefault();first?.focus();}
    });
  }
  const links=[...dossier.querySelectorAll('.trust-contents a')],sections=[...dossier.querySelectorAll('.trust-section')];
  function highlight(){
    const top=dossier.getBoundingClientRect().top+80;
    let current=sections[0];for(const s of sections)if(s.getBoundingClientRect().top<=top)current=s;
    links.forEach(a=>{if(a.hash==='#'+current.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
  }
  dossier.addEventListener('scroll',highlight,{passive:true});
  links.forEach(a=>a.addEventListener('click',event=>{event.preventDefault();const s=root.getElementById(a.hash.slice(1));dossier.scrollTop+=s.getBoundingClientRect().top-dossier.getBoundingClientRect().top-24;highlight();}));
  if(location.hash==='#why-trust'){const button=root.querySelector('[data-open-trust]');if(button)show(topic,button);}
}
if(typeof document!=='undefined')mountTrust();
